g = planarity.networkx_graph(pg)

# Normalise drawplanar attribute names across planarity versions.
# Newer planarity exposes 'vertex_position'/'vertex_start'/'vertex_end'
# for nodes and 'edge_position'/'edge_start'/'edge_end' for edges,
# whereas older versions used 'pos'/'start'/'end' directly.
for _, _data in g.nodes(data=True):
    for _old, _new in (('pos', 'vertex_position'),
                       ('start', 'vertex_start'),
                       ('end', 'vertex_end')):
        if _old not in _data and _new in _data:
            _data[_old] = _data[_new]
for _, _, _data in g.edges(data=True):
    for _old, _new in (('pos', 'edge_position'),
                       ('start', 'edge_start'),
                       ('end', 'edge_end')):
        if _old not in _data and _new in _data:
            _data[_old] = _data[_new]
